std::vector<Polygon2d> faces;
for (auto face = arr.faces_begin(); face != arr.faces_end(); ++face) {
    if (!face->is_unbounded()) {
        Polygon2d polygon;
        auto circulator = face->outer_ccb();
        auto start = circulator;
        do {
            double x, y;
            internal::getCoordinates(circulator->source()->point(), x, y);
            polygon.pushBack(Point2d(x, y));
        } while (++circulator != start);

        // Check if the polygon is valid (non-empty and simple)
        if (polygon.size() >= 3) {
            faces.push_back(polygon);
        }
    }
}
return faces;

